import torch, b200probe as bp, inspect, statistics
print(inspect.signature(bp.cuda_kernel)); print((bp.cuda_kernel.__doc__ or '')[:600])
src = r'''
extern "C" __global__ void __launch_bounds__(256,8)
rd(const float* __restrict__ x, int nchunks, int* counter, int* smids, int mode, int nactive, float* out) {
  unsigned smid; asm volatile("mov.u32 %0, %%smid;" : "=r"(smid));
  if (threadIdx.x==0) smids[blockIdx.x] = smid;
  bool gate = false;
  if (mode==1) gate = smid & 1;
  else if (mode==2) gate = smid >= 74;
  else if (mode==3) gate = smid < 74;
  else if (mode==4) gate = ((smid * 2654435761u) >> 31) & 1;
  else if (mode==5) gate = (smid % 4) != 0;   // 37 SMs
  if (gate) return;
  __shared__ int s_r;
  if (threadIdx.x==0) s_r = atomicAdd(counter, 1);
  __syncthreads();
  int r = s_r;
  float acc = 0.f;
  for (int c = r; c < nchunks; c += nactive) {
    const float* p = x + (size_t)c*8192 + threadIdx.x*8;
    float v[4][8];
    #pragma unroll
    for (int u=0;u<4;u++)
      asm volatile("ld.global.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
        : "=f"(v[u][0]),"=f"(v[u][1]),"=f"(v[u][2]),"=f"(v[u][3]),"=f"(v[u][4]),"=f"(v[u][5]),"=f"(v[u][6]),"=f"(v[u][7]) : "l"(p+u*2048));
    #pragma unroll
    for (int u=0;u<4;u++) for(int i=0;i<8;i++) acc += v[u][i];
  }
  if (acc == 1234.5f) out[0]=acc;
}
'''
k = bp.cuda_kernel(src, "rd")
NB = 400*2**20
x = torch.randn(NB//4, device='cuda')
nchunks = NB//32768
cnt = torch.zeros(1, dtype=torch.int32, device='cuda')
G = 148*8
smids = torch.zeros(G, dtype=torch.int32, device='cuda')
out = torch.zeros(1, device='cuda')
fl = torch.empty(2*126*2**20//4, device='cuda')
k((G,), (256,), x, nchunks, cnt, smids, 0, G, out); torch.cuda.synchronize()
s = smids.cpu().tolist()
ss = sorted(set(s)); print("distinct smids", len(ss), "min", min(ss), "max", max(ss))
from collections import Counter
print("CTAs per SM counts", Counter(Counter(s).values()))
print("blockIdx 0..40 smids", s[:40])
def nact(mode):
    def g(m):
        if mode==1: return m&1
        if mode==2: return m>=74
        if mode==3: return m<74
        if mode==4: return ((m*2654435761)&0xffffffff)>>31
        if mode==5: return (m%4)!=0
        return 0
    return 8*sum(1 for m in ss if not g(m))
res = {}
for rep in range(3):
  for mode in [0,1,2,3,4,5]:
    na = nact(mode)
    ts=[]
    for it in range(4):
        fl.zero_(); fl.sum(); cnt.zero_()
        torch.cuda.synchronize()
        e0=torch.cuda.Event(enable_timing=True); e1=torch.cuda.Event(enable_timing=True)
        e0.record(); k((G,), (256,), x, nchunks, cnt, smids, mode, na, out); e1.record(); torch.cuda.synchronize()
        ts.append(e0.elapsed_time(e1)*1000)
        assert cnt.item()==na, (mode, cnt.item(), na)
    res.setdefault(mode, []).append(statistics.median(ts))
for mode,v in res.items():
    t = statistics.median(v); print(f"mode {mode} activeSMs {nact(mode)//8} t {t:.1f} us  {NB/t/1e6:.2f} TB/s  reps {[round(a,1) for a in v]}")

import torch, b200probe as bp, numpy as np
src = r'''
extern "C" __global__ void lat(const float* __restrict__ base, const int* __restrict__ perm, int n, int* flag, int* lat, int mode) {
  unsigned smid; asm volatile("mov.u32 %0, %%smid;" : "=r"(smid));
  if (threadIdx.x != 0) return;
  if (atomicCAS(flag + smid, 0, 1) != 0) return;
  int dep = 0;
  for (int j = 0; j < n; ++j) {
    int idx = perm[j] + dep;
    long long t0, t1; float v;
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t0) : "r"(idx));
    asm volatile("ld.global.cg.f32 %0, [%1];" : "=f"(v) : "l"(base + (size_t)idx * 32));
    int iv = __float_as_int(v);
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t1) : "r"(iv));
    dep = iv & 0;  // keep dependence (data are zeros)
    dep = (iv == 0x7f7f7f7f) ? 1 : 0;
    if (mode) lat[smid * n + perm[j]] = (int)(t1 - t0);
  }
}
'''
k = bp.cuda_kernel(src, "lat")
N = 16384
buf = torch.zeros(8*2**20//4, device='cuda')
p = buf.data_ptr(); off = ((p + 2**21 - 1)//2**21)*2**21 - p
base = buf[off//4:]
print("base mod 2MB", base.data_ptr() % 2**21)
perm = torch.randperm(N, device='cuda').int()
flag = torch.zeros(148, dtype=torch.int32, device='cuda')
lat = torch.zeros(148*N, dtype=torch.int32, device='cuda')
G = 148*16
k((G,), (32,), base, perm, N, flag, lat, 0); torch.cuda.synchronize()   # warm
flag.zero_()
k((G,), (32,), base, perm, N, flag, lat, 1); torch.cuda.synchronize()
print("SMs measured", flag.sum().item())
L = lat.view(148, N).cpu().numpy().astype(np.float64)
print("overall percentiles", np.percentile(L, [1,5,10,25,50,75,90,95,99]).round(0))
h, e = np.histogram(np.clip(L, 0, 2000), bins=40, range=(0,2000))
print("hist (50-cycle bins):", list(zip(e[:-1].astype(int), h)))
sm_med = np.median(L, axis=1); print("per-SM median min/max", sm_med.min(), sm_med.max())
np.save('/tmp/lat_warm.npy', L)
# 2-cluster threshold
thr = np.median(L)
B = (L > thr).astype(np.float64)
M = B - B.mean()
u, s, vt = np.linalg.svd(M, full_matrices=False)
print("singular values", s[:5].round(1))
die = (u[:,0] > 0).astype(int); part = (vt[0] > 0).astype(int)
print("die split counts", np.bincount(die), "smids die1:", np.where(die==1)[0].tolist())
print("line part counts", np.bincount(part))
addr = np.arange(N) * 128
for b in range(7, 21):
    bit = (addr >> b) & 1
    print("bit", b, "agree", round(float((bit == part).mean()), 3))
best = []
for b1 in range(7, 21):
    for b2 in range(b1+1, 21):
        x = ((addr >> b1) ^ (addr >> b2)) & 1
        best.append((abs((x == part).mean() - 0.5), b1, b2))
best.sort(reverse=True); print("best xor pairs", best[:5])
# near/far means
near = np.where(die[:,None] == part[None,:], L, np.nan); far = np.where(die[:,None] != part[None,:], L, np.nan)
print("mean lat group A", np.nanmean(near), "group B", np.nanmean(far))

import torch, b200probe as bp, numpy as np
src = r'''
extern "C" __global__ void lat(const int* __restrict__ base, const int* __restrict__ perm, int n, int* flag, int* lat, int mode) {
  unsigned smid; asm volatile("mov.u32 %0, %%smid;" : "=r"(smid));
  if (threadIdx.x != 0) return;
  if (atomicCAS(flag + smid, 0, 1) != 0) return;
  for (int j = 0; j < n; ++j) {
    int idx = perm[j];
    long long t0, t1;
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t0) : "r"(idx) : "memory");
    #pragma unroll
    for (int r = 0; r < 16; ++r)
      asm volatile("ld.global.cg.s32 %0, [%1];" : "=r"(idx) : "l"(base + (size_t)idx * 32) : "memory");
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t1) : "r"(idx) : "memory");
    if (mode) lat[smid * n + perm[j]] = (int)(t1 - t0) + (idx & 0x40000000);
  }
}
'''
k = bp.cuda_kernel(src, "lat")
N = 16384
buf = torch.zeros(8*2**20//4, dtype=torch.int32, device='cuda')
p = buf.data_ptr(); off = ((p + 2**21 - 1)//2**21)*2**21 - p
base = buf[off//4:]
base[:N*32].view(N, 32)[:, 0] = torch.arange(N, device='cuda', dtype=torch.int32)
perm = torch.randperm(N, device='cuda').int()
flag = torch.zeros(148, dtype=torch.int32, device='cuda')
lat = torch.zeros(148*N, dtype=torch.int32, device='cuda')
G = 148*16
k((G,), (32,), base, perm, N, flag, lat, 0); torch.cuda.synchronize()
flag.zero_()
k((G,), (32,), base, perm, N, flag, lat, 1); torch.cuda.synchronize()
L = lat.view(148, N).cpu().numpy().astype(np.float64) / 16
np.save('/tmp/lat_warm.npy', L)
print("overall percentiles", np.percentile(L, [1,5,10,25,50,75,90,95,99]).round(1))
h, e = np.histogram(L, bins=30, range=(np.percentile(L,0.5), np.percentile(L,99.5)))
print("hist:", [(round(a), int(b)) for a, b in zip(e[:-1], h)])
sm_med = np.median(L, axis=1); print("per-SM median", np.round(sm_med[:20],1), "min/max", sm_med.min(), sm_med.max())
thr = np.median(L)
B = (L > thr).astype(np.float64); M = B - B.mean()
u, s, vt = np.linalg.svd(M, full_matrices=False)
print("singular values", s[:5].round(1))
die = (u[:,0] > 0).astype(int); part = (vt[0] > 0).astype(int)
print("die split counts", np.bincount(die), "smids die1:", np.where(die==1)[0].tolist())
print("line part counts", np.bincount(part))
addr = np.arange(N) * 128
for b in range(7, 21):
    bit = (addr >> b) & 1
    print("bit", b, "agree", round(float((bit == part).mean()), 3))
best = []
for b1 in range(7, 21):
    for b2 in range(b1+1, 21):
        x = ((addr >> b1) ^ (addr >> b2)) & 1
        best.append((round(abs((x == part).mean() - 0.5),3), b1, b2))
best.sort(reverse=True); print("best xor pairs", best[:5])
same = die[:,None] == part[None,:]
print("mean lat same-class", L[same].mean().round(1), "other", L[~same].mean().round(1))

import torch, b200probe as bp, numpy as np
src = r'''
extern "C" __global__ void cold(const int* __restrict__ base, const int* __restrict__ perm, int n, int* flag, int target, int* lat) {
  __shared__ int s[32];
  unsigned smid; asm volatile("mov.u32 %0, %%smid;" : "=r"(smid));
  if (threadIdx.x < 32) s[threadIdx.x] = 0;
  __syncwarp();
  if (threadIdx.x != 0 || smid != (unsigned)target) return;
  if (atomicCAS(flag, 0, 1) != 0) return;
  unsigned sb = (unsigned)__cvta_generic_to_shared(s);
  for (int j = 0; j < n; ++j) {
    int idx = perm[j];
    long long t0, t1; int v;
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t0) : "r"(idx) : "memory");
    asm volatile("ld.global.cg.s32 %0, [%1];" : "=r"(v) : "l"(base + (size_t)idx * 32) : "memory");
    #pragma unroll
    for (int r = 0; r < 8; ++r)
      asm volatile("ld.shared.s32 %0, [%1];" : "=r"(v) : "r"(sb + v * 4) : "memory");
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t1) : "r"(v) : "memory");
    lat[idx] = (int)(t1 - t0) + v;
  }
}
'''
k = bp.cuda_kernel(src, "cold")
N = 16384
buf = torch.zeros(8*2**20//4, dtype=torch.int32, device='cuda')
p = buf.data_ptr(); off = ((p + 2**21 - 1)//2**21)*2**21 - p
base = buf[off//4:]
perm = torch.randperm(N, device='cuda').int()
flag = torch.zeros(1, dtype=torch.int32, device='cuda')
lat = torch.zeros(N, dtype=torch.int32, device='cuda')
fl = torch.empty(2*126*2**20//4, device='cuda')
targets = [0, 2, 37, 70, 74, 76, 110, 146, 0, 74]
res = []
for t in targets:
    fl.zero_(); fl.sum(); flag.zero_(); torch.cuda.synchronize()
    k((148*8,), (32,), base, perm, N, flag, t, lat); torch.cuda.synchronize()
    assert flag.item() == 1
    res.append(lat.cpu().numpy().astype(np.float64))
R = np.array(res)
np.save('/tmp/cold.npy', R)
for t, r in zip(targets, R):
    print("sm", t, "pct", np.percentile(r, [5,25,50,75,95]).round(0))
r = R[0]; h, e = np.histogram(r, bins=30, range=(np.percentile(r,1), np.percentile(r,99)))
print("hist sm0:", [(round(a), int(b)) for a, b in zip(e[:-1], h)])
C = np.corrcoef(R); print("corr matrix\n", np.round(C, 2))
def wht(a):
    a = a.copy(); hh = 1
    while hh < len(a):
        a = a.reshape(-1, 2*hh); x = a[:, :hh].copy(); y = a[:, hh:].copy()
        a[:, :hh] = x + y; a[:, hh:] = x - y; a = a.reshape(-1); hh *= 2
    return a
for i, t in enumerate(targets[:8]):
    v = R[i] - np.median(R[i]); v = np.sign(v)
    w = wht(v) / N
    top = np.argsort(-np.abs(w))[1:6]
    print("sm", t, "top masks (line-index bits; addr bit = +7)", [(bin(m), round(float(w[m]),3)) for m in top])

import torch, b200probe as bp, numpy as np
src = r'''
extern "C" __global__ void cold(const int* __restrict__ base, const int* __restrict__ perm, int n, int* flag, int target, int* lat) {
  __shared__ int s[32];
  unsigned smid; asm volatile("mov.u32 %0, %%smid;" : "=r"(smid));
  if (threadIdx.x < 32) s[threadIdx.x] = 0;
  __syncwarp();
  if (threadIdx.x != 0 || smid != (unsigned)target) return;
  if (atomicCAS(flag, 0, 1) != 0) return;
  unsigned sb = (unsigned)__cvta_generic_to_shared(s);
  for (int j = 0; j < n; ++j) {
    int idx = perm[j];
    long long t0, t1; int v;
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t0) : "r"(idx) : "memory");
    asm volatile("ld.global.cg.s32 %0, [%1];" : "=r"(v) : "l"(base + (size_t)idx * 32) : "memory");
    #pragma unroll
    for (int r = 0; r < 8; ++r)
      asm volatile("ld.shared.s32 %0, [%1];" : "=r"(v) : "r"(sb + v * 4) : "memory");
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t1) : "r"(v) : "memory");
    lat[j] = (int)(t1 - t0) + v;
  }
}
'''
k = bp.cuda_kernel(src, "cold")
N = 16384
buf = torch.zeros(8*2**20//4, dtype=torch.int32, device='cuda')
p = buf.data_ptr(); off = ((p + 2**21 - 1)//2**21)*2**21 - p
base = buf[off//4:]
flag = torch.zeros(1, dtype=torch.int32, device='cuda')
lat = torch.zeros(N, dtype=torch.int32, device='cuda')
fl = torch.empty(2*126*2**20//4, device='cuda')
def meas(t, perm):
    fl.zero_(); fl.sum(); flag.zero_(); torch.cuda.synchronize()
    k((148*8,), (32,), base, perm, perm.numel(), flag, t, lat); torch.cuda.synchronize()
    assert flag.item() == 1
    return lat[:perm.numel()].cpu().numpy().astype(np.float64)
permall = torch.randperm(N, device='cuda').int()
pa = permall.cpu().numpy()
a = np.empty(N); a[pa] = meas(0, permall)
b = np.empty(N); b[pa] = meas(2, permall)
def cls(x): return np.digitize(x, [950, 1320])  # 0 fast, 1 mid, 2 slow
ca, cb = cls(a), cls(b)
J = np.zeros((3,3), int)
for i in range(3):
    for j in range(3): J[i,j] = ((ca==i)&(cb==j)).sum()
print("joint classes rows=SM0 (fast,mid,slow) cols=SM2\n", J)
# per-SM die map with 512 lines that are fast for exactly one of SM0/SM2
sel = np.where(((ca==0)&(cb==1)) | ((ca==1)&(cb==0)))[0][:512]
print("discriminating lines", len(sel))
ps = torch.tensor(sel, dtype=torch.int32, device='cuda')
ref = (ca[sel]==0).astype(float)
g = []
for t in range(148):
    v = meas(t, ps)
    g.append(np.corrcoef(v < 950, ref)[0,1])
g = np.array(g)
print("corr with SM0 pattern:", np.round(g, 2).tolist())
grpA = np.where(g > 0.5)[0]; grpB = np.where(g < -0.5)[0]
print("group A (like SM0)", len(grpA), grpA.tolist())
print("group B (like SM2)", len(grpB), grpB.tolist())
print("ambiguous", np.where(np.abs(g) <= 0.5)[0].tolist())

import torch, b200probe as bp, numpy as np, statistics
A_SMS = [0,1,10,11,12,13,14,15,16,17,26,27,28,29,30,31,32,33,42,43,44,45,46,47,48,49,58,59,60,61,62,63,64,65,74,75,76,77,78,79,88,89,90,91,92,93,102,103,104,105,106,107,116,117,118,119,120,121,130,131,132,133,134,135,136,137,138,139,140,141,142,143]
diemap = torch.ones(148, dtype=torch.int32); diemap[A_SMS] = 0; diemap = diemap.cuda()
src = r'''
extern "C" __global__ void cls(const int* __restrict__ base, int nlines, const int* __restrict__ diemap, int grp, int* flag, int* cnt, int nlanes, int* lat) {
  __shared__ int s[32];
  unsigned smid; asm volatile("mov.u32 %0, %%smid;" : "=r"(smid));
  s[threadIdx.x] = 0; __syncwarp();
  if (diemap[smid] != grp) return;
  __shared__ int win, rk;
  if (threadIdx.x == 0) { win = atomicCAS(flag + smid, 0, 1); if (win == 0) rk = atomicAdd(cnt, 1); }
  __syncwarp();
  if (win != 0) return;
  int g = rk * 32 + threadIdx.x;
  unsigned sb = (unsigned)__cvta_generic_to_shared(s);
  for (int j = g; j < nlines; j += nlanes) {
    long long t0, t1; int v;
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t0) : "r"(j) : "memory");
    asm volatile("ld.global.cg.s32 %0, [%1];" : "=r"(v) : "l"(base + (size_t)j * 32) : "memory");
    #pragma unroll
    for (int r = 0; r < 8; ++r) asm volatile("ld.shared.s32 %0, [%1];" : "=r"(v) : "r"(sb + v * 4) : "memory");
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t1) : "r"(v) : "memory");
    lat[j] = (int)(t1 - t0) + v;
  }
}
extern "C" __global__ void __launch_bounds__(256,8)
rdl(const float* __restrict__ x, const int* __restrict__ L0, int n0, const int* __restrict__ L1, int n1,
    const int* __restrict__ diemap, int* cnt, int nct0, int nct1, float* out) {
  unsigned smid; asm volatile("mov.u32 %0, %%smid;" : "=r"(smid));
  int g = diemap[smid];
  __shared__ int s_r;
  if (threadIdx.x == 0) s_r = atomicAdd(cnt + g, 1);
  __syncthreads();
  const int* L = g ? L1 : L0; int n = g ? n1 : n0; int nct = g ? nct1 : nct0;
  float acc = 0.f;
  for (int b = s_r * 256; b < n; b += nct * 256) {
    float v[4][8]; int id[4];
    #pragma unroll
    for (int u = 0; u < 4; u++) { int e = b + u * 64 + (threadIdx.x >> 2); id[u] = e < n ? L[e] : -1; }
    #pragma unroll
    for (int u = 0; u < 4; u++) {
      const float* p = x + (size_t)(id[u] < 0 ? 0 : id[u]) * 32 + (threadIdx.x & 3) * 8;
      asm volatile("ld.global.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
        : "=f"(v[u][0]),"=f"(v[u][1]),"=f"(v[u][2]),"=f"(v[u][3]),"=f"(v[u][4]),"=f"(v[u][5]),"=f"(v[u][6]),"=f"(v[u][7]) : "l"(p));
    }
    #pragma unroll
    for (int u = 0; u < 4; u++) for (int i = 0; i < 8; i++) acc += v[u][i];
  }
  if (acc == 1234.5f) out[0] = acc;
}
'''
kc = bp.cuda_kernel(src, "cls"); kr = bp.cuda_kernel(src, "rdl")
NB = 400 * 2**20; NL = NB // 128
x = torch.zeros(NB // 4 + 2**19, dtype=torch.int32, device='cuda')
p = x.data_ptr(); off = ((p + 2**21 - 1)//2**21)*2**21 - p
x = x[off//4: off//4 + NB//4]
fl = torch.empty(2*126*2**20//4, device='cuda')
flag = torch.zeros(148, dtype=torch.int32, device='cuda'); cnt = torch.zeros(2, dtype=torch.int32, device='cuda')
lat = torch.zeros(NL, dtype=torch.int32, device='cuda')
res = []
for grp, nsm in [(0, 72), (1, 76)]:
    fl.zero_(); fl.sum(); flag.zero_(); cnt.zero_(); torch.cuda.synchronize()
    kc((148*8,), (32,), x, NL, diemap, grp, flag, cnt, nsm*32, lat); torch.cuda.synchronize()
    assert cnt[0].item() == nsm, cnt
    res.append(lat.cpu().numpy().astype(np.int32))
a, b = res
print("A pct", np.percentile(a, [5,25,50,75,95]), "B pct", np.percentile(b, [5,25,50,75,95]))
d = a.astype(np.int64) - b
nearA = d < -150; nearB = d > 150
print("nearA", nearA.mean().round(3), "nearB", nearB.mean().round(3), "ambig", (~nearA & ~nearB).mean().round(3))
c = np.where(nearA, 0, np.where(nearB, 1, -1))
for gran in [2, 4, 8, 16, 32]:
    cc = c[: NL // gran * gran].reshape(-1, gran)
    ok = (cc >= 0).all(1)
